questionvariables.text:
/* Randomize side (even numbers between 12 m and 128 m) */
side : 2 * (rand(59) + 6);

/* Randomize height (even numbers less than side, between 4 m and side - 2) */
height : 2 * (rand(floor(side/2 - 1)) + 2);

/* Calculations */
triangle_area : (1/2) * side * height;
total_area : 5 * triangle_area;

/* Common Mistakes for PRT */
m1 : 5 * side * height; /* Forgot the 1/2 in the triangle formula */
m2 : triangle_area;     /* Forgot to multiply by 5 */
m3 : side * height;     /* Base x Height (treating one triangle like a rectangle) */
